using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RecycleActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/RecycleActionCustomDescription", order = 0)]
public class RecycleActionCustomDescription : CustomBattleActionDescription
{
	private const string recyclePreviewID = "RecyclePreview";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = "";
		if (base.isOnBattleScene && ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.PlayerUnlockablesState)
		{
			int num = Mathf.FloorToInt((float)(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RecycledSentinelAmount + 1) / 2f);
			text = "\n" + Smart.Format(base.localizationManager.GetLocalizedString("RecyclePreview"), num);
		}
		return Smart.Format(GetRawLocalizedDescription(battleAction), 1, 2) + text;
	}
}
